		cacheBoost := 0.20
		if inputLen > 256 {
			cacheBoost = 0.35
		}
		scores[snap.ID] *= (1.0 - cacheBoost + cacheBoost*snap.CacheHitRate)

		// KV pressure penalty
		if snap.KVUtilization > 0.65 {
			kvPenalty := (snap.KVUtilization - 0.65) / 0.35
			scores[snap.ID] *= (1.0 - 0.55*kvPenalty*kvPenalty)
		}

		// Large inputs: prefer more free memory
		if inputLen > 200 && snap.FreeKVBlocks > 0 {
			memBonus := float64(snap.FreeKVBlocks) / float64(snap.FreeKVBlocks+160)
			scores[snap.ID] *= (1.0 + 0.15*memBonus)
		}

		// Floor
		if scores[snap.ID] < 0.001 {
			scores[snap.ID] = 0.001
		}
	}

	// Argmax selection
	bestScore := -1.0
	bestIdx := 0
	for i, snap := range snapshots {
		if scores[snap.ID] > bestScore {
			bestScore = scores[snap.ID]
			bestIdx = i
		}
	}
	// EVOLVE-BLOCK-END

	// Notify observers of routing decision (stateful scorers update their state)
	for _, obs := range ws.observers {
		obs(req, snapshots[bestIdx].ID)
	}

	return NewRoutingDecisionWithScores(
